  {
    titulo = "Páramos de Poniente", min = 18, max = 20,
    entrenar = "Nivel 20 = gran entrenamiento en Ventormenta con Suma Sacerdotisa Laurena, en la Catedral de la Luz: Sanación relámpago, Peste devoradora (daño en el tiempo que además te cura; en Forever la aprenden todas las razas), Fuego interno (rango 2) y Renovar (rango 3). Talento 20: Tortura mental, tu hechizo de relleno. Ella misma te da tu misión de raza del 20.",
    equipo = "Objetivo: completar la cadena [La hermandad de los Defias] hasta Las Minas de la Muerte. La última parte da <Bastón de Páramos de Poniente>, un buen bastón. En la mazmorra, Cocinitas suelta <Vara para remover galletas>: una de las mejores varitas de leveo. Mazmorras (opcional): las de tu nivel dan mucha experiencia, por sus enemigos y por sus misiones, y conviene hacerlas; tú decides si vas.",
    profesion = "Sastrería 55-100: <Madeja de paño de lana>, <Manteo de lana> y <Hombreras de lana con doble pespunte>. Primeros auxilios: <Venda de lana>.",
    pasos = {
      { t = "Coge el Tranvía Subterráneo a Ventormenta y activa allí el vuelo con Dungar Tragolargo. Si eres enano, entrega [Oración desesperada] a Suma Sacerdotisa Laurena en la Catedral de la Luz: aprendes Oración desesperada y ella misma te enseña su rango 2. Después baja a Poniente.", wp = { { m = 1453, z = "Ciudad de Ventormenta", x = 71.3, y = 72.2, n = "Dungar Tragolargo", npc = 352 }, { m = 1453, z = "Ciudad de Ventormenta", x = 49.5, y = 44.6, n = "Entregar: Oración desesperada (Suma Sacerdotisa Laurena)", q = 5637, a = "T", raza = "Dwarf" } }, comprobar = { llegar = 1436 } },
      { t = "Colina del Centinela: activa el vuelo con Thor y acepta [La hermandad de los Defias] de Gryan Mantorrecio, [Pañuelos rojos de cuero] de Explorador Galiaan y [En patrulla por Páramos de Poniente] de Capitán Danuvin. No cambies la piedra de hogar: la usarás para volver a Thelsamar.", wp = { { m = 1436, z = "Páramos de Poniente", x = 56.5, y = 52.6, n = "Thor", npc = 523 }, { m = 1436, z = "Páramos de Poniente", x = 56.3, y = 47.5, n = "Recoger: La hermandad de los Defias (Gryan Mantorrecio)", q = 65, a = "A" }, { m = 1436, z = "Páramos de Poniente", x = 54.0, y = 53.0, n = "Recoger: Pañuelos rojos de cuero (Explorador Galiaan)", q = 153, a = "A" }, { m = 1436, z = "Páramos de Poniente", x = 56.4, y = 47.6, n = "Recoger: En patrulla por Páramos de Poniente (Capitán Danuvin)", q = 102, a = "A" } } },
      { t = "Granja de los Saldean (norte): Granjero Saldean te da [Campos de la muerte]: gólems de la cosecha en los campos de alrededor.", wp = { { m = 1436, z = "Páramos de Poniente", x = 56.0, y = 31.2, n = "Recoger: Campos de la muerte (Granjero Saldean)", q = 9, a = "A" }, { m = 1436, z = "Páramos de Poniente", x = 53.5, y = 31.7, n = "Objetivo: Campos de la muerte", q = 9, a = "C" }, { m = 1436, z = "Páramos de Poniente", x = 56.0, y = 31.2, n = "Entregar: Campos de la muerte (Granjero Saldean)", q = 9, a = "T" } } },
