  {
    titulo = "Marjal Revolcafango", min = 39, max = 42,
    entrenar = "Nivel 40: Forma de las Sombras (talento: más daño de Sombra, tus hechizos de Sombra cuestan la mitad y recibes menos daño físico; en la forma no puedes curar), Explosión mental (rango 6), Palabra de las Sombras: muerte (rango 2) y doble especialización (10 de oro en tu instructor). Montura: aprende equitación y compra tu primera montura en Dun Morogh. Talentos 41-44: Enfoque de las Sombras (5/5).",
    equipo = "Con Forma de las Sombras, busca en la subasta piezas con daño de Sombra, Intelecto y Espíritu. Mazmorras (opcional): las de tu nivel dan mucha experiencia, por sus enemigos y por sus misiones, y conviene hacerlas; tú decides si vas.",
    profesion = "En Theramore: Sastrería artesana con Timoteo Valión (200 y nivel 35) y [Atenciones médicas] de Primeros auxilios con Doctor Gustaf VanHowzen (225).",
    pasos = {
      { t = "Nivel 40: vuela de Costasur a Forjaz y entrena con Sumo Sacerdote Rohan: Explosión mental (rango 6), Palabra de las Sombras: muerte (rango 2), Fuego interno (rango 4) y Espíritu divino (rango 2). Es caro: guarda oro también para la montura. Al hablar con el instructor elige entrenar: la guía aprende sola lo recomendado (Mayús para hacerlo a mano).", wp = { { m = 1455, z = "Forjaz", x = 24.7, y = 8.2, n = "Sumo Sacerdote Rohan", npc = 11406 } }, comprobar = { hechizos = { 8106 } } },
      { t = "Montura: si eres enano, al este de Kharanos aprende equitación con Ulthaan Ferrocorno y compra un carnero a Veron Calmámbar; si eres gnomo, en el Depósito de Rodaacero, al norte de Kharanos, aprende con Binjy Plumasilba y compra un mecazancudo a Milli Plumasilba.", wp = { { m = 1426, z = "Dun Morogh", x = 63.8, y = 50.1, n = "Ulthaan Ferrocorno", npc = 4772, raza = "Dwarf" }, { m = 1426, z = "Dun Morogh", x = 63.5, y = 50.6, n = "Veron Calmámbar", npc = 1261, raza = "Dwarf" }, { m = 1426, z = "Dun Morogh", x = 49.1, y = 48.1, n = "Binjy Plumasilba", npc = 7954, raza = "Gnome" }, { m = 1426, z = "Dun Morogh", x = 49.1, y = 48.0, n = "Milli Plumasilba", npc = 7955, raza = "Gnome" } } },
      { t = "Vuela a Menethil y coge el barco a Theramore. Compra 3 <Especias calmantes> a Helenia Olden, que las pedirá \"Ojolodo\" Jarl. Morgan Stern te da [Sopa de fangorroca con tropezones]: tortugas Fangorroca en la costa del Marjal. La segunda parte ([... con tropezones]) es del Pantano de las Penas: no la cojas.", wp = { { m = 1445, z = "Marjal Revolcafango", x = 66.4, y = 51.5, n = "Helenia Olden", npc = 4897 }, { m = 1445, z = "Marjal Revolcafango", x = 66.3, y = 45.5, n = "Recoger: Sopa de fangorroca con tropezones (Morgan Stern)", q = 1204, a = "A" }, { m = 1445, z = "Marjal Revolcafango", x = 59.5, y = 52.9, n = "Objetivo: Sopa de fangorroca con tropezones", q = 1204, a = "C" }, { m = 1445, z = "Marjal Revolcafango", x = 66.3, y = 45.5, n = "Entregar: Sopa de fangorroca con tropezones (Morgan Stern)", q = 1204, a = "T" } } },
      { t = "Marjal: [¡Qué hambre!] (cabezas de aleta de fango al norte).", wp = { { m = 1445, z = "Marjal Revolcafango", x = 35.1, y = 38.3, n = "Recoger: ¡Qué hambre! (Fangolpe Piesucio)", q = 1177, a = "A" }, { m = 1445, z = "Marjal Revolcafango", x = 57.7, y = 15.2, n = "Objetivo: ¡Qué hambre!", q = 1177, a = "C" }, { m = 1445, z = "Marjal Revolcafango", x = 35.1, y = 38.3, n = "Entregar: ¡Qué hambre! (Fangolpe Piesucio)", q = 1177, a = "T" } } },
      { t = "Pantano de la Luz: dale las especias a \"Ojolodo\" Jarl ([Especias calmantes]) y haz [Jarl necesita ojos]: arañas Niebla Negra, al oeste.", wp = { { m = 1445, z = "Marjal Revolcafango", x = 55.4, y = 26.3, n = "Recoger: Especias calmantes (\"Ojolodo\" Jarl)", q = 1218, a = "A" }, { m = 1445, z = "Marjal Revolcafango", x = 55.4, y = 26.3, n = "Entregar: Especias calmantes (\"Ojolodo\" Jarl)", q = 1218, a = "T" }, { m = 1445, z = "Marjal Revolcafango", x = 55.4, y = 26.3, n = "Recoger: Jarl necesita ojos (\"Ojolodo\" Jarl)", q = 1206, a = "A" }, { m = 1445, z = "Marjal Revolcafango", x = 32.6, y = 22.1, n = "Objetivo: Jarl necesita ojos", q = 1206, a = "C" }, { m = 1445, z = "Marjal Revolcafango", x = 55.4, y = 26.3, n = "Entregar: Jarl necesita ojos (\"Ojolodo\" Jarl)", q = 1206, a = "T" } } },
